create or replace function public.school_admin_add_other_member(p_full_name text,p_password text,p_role_title text default null,p_department text default null,p_phone text default null,p_email text default null,p_details text default null)
returns jsonb language plpgsql security definer set search_path='' as $$ declare v_id uuid; v_login text; v_hash text; begin if not public.store_is_admin() then raise exception 'Not authorized'; end if; if nullif(trim(p_full_name),'') is null or nullif(p_password,'') is null then raise exception 'Name and password are required'; end if; v_hash:=crypt(p_password,gen_salt('bf')); insert into public.school_other_members(full_name,role_title,department,phone,email,details,login_password,password_hash) values(trim(p_full_name),nullif(trim(p_role_title),''),nullif(trim(p_department),''),nullif(trim(p_phone),''),nullif(trim(p_email),''),nullif(trim(p_details),''),p_password,v_hash) returning id,other_id into v_id,v_login; insert into public.store_users(people_profile_id,login_id,password_hash,is_active) values(null,lower(v_login),v_hash,true); return jsonb_build_object('id',v_id,'login_id',v_login,'password',p_password); end; $$;
grant execute on function public.school_admin_add_other_member(text,text,text,text,text,text,text) to authenticated;

create or replace function public.school_admin_list_other_members()
returns jsonb language plpgsql security definer set search_path='' as $$ begin if not public.store_is_admin() then raise exception 'Not authorized'; end if; return coalesce((select jsonb_agg(jsonb_build_object('id',id,'member_id',other_id,'member_type','other','full_name',full_name,'password',login_password,'role_title',role_title,'department',department,'phone',phone,'email',email,'details',details,'is_active',is_active) order by full_name) from public.school_other_members),'[]'::jsonb); end; $$;
grant execute on function public.school_admin_list_other_members() to authenticated;
